//
// Active map (per word, p = pavel, T = tavel, c = coldry, w_m = wkl(m) for m = 0,1,2,3,5,6; tab is a constant table):
//   plog = log p;  fp = 5*(preflog[jp-1] - plog);  ft = (T - tref[jp-1])/15 - (jt-3);  ft1 = (T - tref[jp])/15 - (jt1-3)
//   water = w0/c;  scalefac = p*stpfac/T;  forfac = scalefac/(1+water)
//   trop:   forfrac = (332-T)/36 - indfor;  selffac = water*forfac;  selffrac = (T-188)/7.2 - (indself+7)
//   !trop:  forfrac = (T-188)/36 - 1;       selffac = selffrac = 0
//   colX = 1e-20*w_m (colco2/coln2o/colch4/colo2 fall back to 1e-32*c where the primal 1e-20*w_m is +-0)
//   colmol = 1e-20*c + colh2o;  co2mult = (colco2 - 3.55e-24*c)*272.63*exp(-1919.4/T) / (8.7604e-4*T)
//   fac10 = (1-fp)*ft;  fac00 = (1-fp)*(1-ft);  fac11 = fp*ft1;  fac01 = fp*(1-ft1)
// Integer outputs (jp, jt, jt1, indself, indfor, trop_flag, low_flag) are piecewise constant: inactive, no tangent.
//
// Frozen-coefficient treatment (documented, the limiter rule): every integer index and branch of the forward is
// taken from the primal trajectory and held fixed in TL and AD. That covers the index clamps
//   jp in [1,58] (capture source 1445), jt and jt1 in [1,4] (1450, 1455), indfor in [1,2] (1475), indself in [1,9]
//   (1481), the troposphere branch plog > 4.56 (1462) and the four EQ0 zero-column fallbacks (1496-1499).
// Inside a bin the map is smooth and the TL is its exact local derivative; a clamped index only extends the bin's
// linear formula (the fraction keeps its slope), so clamping changes no partial. At a bin edge (or a trop/fallback
// switch) the outputs jump by design (taumol re-reads the table at the new index), and the frozen linearisation
// does not see that jump: see RESULT.md range hazards.
//
// Precision (the glue-row rule): the f32 primal words the derivative uses are formed by rsc_primal with the
// forward's own operations in the forward's order (AD/SU/MU/DV = add/sub/mul.rn.f32 and __fdiv_rn with the
// forward's NaN rule, gfk_log/gfk_exp, built --fmad=false --ftz=false); the harness-only __check writes every one
// of the 23 forward outputs from that helper and must be bitwise to the forward image. Local partials are formed
// in double from those f32 words and the f32 inputs, and every written derivative word is rounded to f32 once.
// Primal arguments are the pre-launch words; the kernel writes none of its inputs, so the binding is the plain
// launch value. Tangent outputs are full overwrites; adjoint seeds of the 16 float outputs are consumed (zeroed)
// and the input cotangents are accumulated (one f32 rounding of old + increment). Deterministic: no atomics on
// data words. Refusal: a nonfinite input, partial or written word sets failure slot 0
// (source rrtmg_sw_v842.py:1219:nonfinite).

#define RSC_MX RSW_MXMOL

struct RscP {
  float plog, fp, ft, ft1, water, scalefac, forfac, forfrac, selffac, selffrac;
  float col[6];          // colh2o, colco2, colo3, coln2o, colch4, colo2 (final words, after any fallback)
  bool fb[6];            // fallback taken (colco2, coln2o, colch4, colo2 only)
  float colmol, diff, E, den, co2mult, compfp, fac00, fac01, fac10, fac11;
  int jp, jt, jt1, indself, indfor, trop, low;
};

__device__ __forceinline__ int rsc_row(int i) { return i < 4 ? i : i + 1; }   // 0,1,2,3,5,6

// Forward words for one (column, layer), operation for operation as rsw_setcoef_body (capture source 1423-1508).
__device__ __forceinline__ RscP rsc_primal(int lay, const real *tab, const real *pavel, const real *tavel,
                                           const real *coldry, const real *wkl) {
  RscP k;
  const real *preflog = tab + RSW_T_REF_PREFLOG;
  const real *tref = tab + RSW_T_REF_TREF;
  const real stpfac = DV(296.0f, 1013.0f);
  real plog = rsw_log(pavel[lay]);
  int jpv = (int)SU(36.0f, MU(5.0f, AD(plog, 0.04f)));
  if (jpv < 1) jpv = 1; else if (jpv > 58) jpv = 58;
  int jp1 = jpv + 1;
  real fp = MU(5.0f, SU(preflog[jpv - 1], plog));
  int jtv = (int)AD(3.0f, DV(SU(tavel[lay], tref[jpv - 1]), 15.0f));
  if (jtv < 1) jtv = 1; else if (jtv > 4) jtv = 4;
  real ft = SU(DV(SU(tavel[lay], tref[jpv - 1]), 15.0f), (real)(jtv - 3));
  int jt1v = (int)AD(3.0f, DV(SU(tavel[lay], tref[jp1 - 1]), 15.0f));
  if (jt1v < 1) jt1v = 1; else if (jt1v > 4) jt1v = 4;
  real ft1 = SU(DV(SU(tavel[lay], tref[jp1 - 1]), 15.0f), (real)(jt1v - 3));
  real water = DV(wkl[0 + RSC_MX * lay], coldry[lay]);
  real scalefac = DV(MU(pavel[lay], stpfac), tavel[lay]);
  bool trop = !(plog <= 4.56f);
  k.trop = trop ? 1 : 0;
  k.low = (trop && plog >= 6.62f) ? 1 : 0;
  if (!trop) {
    k.forfac = DV(scalefac, AD(1.0f, water));
    real factor = DV(SU(tavel[lay], 188.0f), 36.0f);
    k.indfor = 3;
    k.forfrac = SU(factor, 1.0f);
    k.selffac = 0.0f; k.selffrac = 0.0f; k.indself = 0;
  } else {
    k.forfac = DV(scalefac, AD(1.0f, water));
    real factor = DV(SU(332.0f, tavel[lay]), 36.0f);
    int idf = (int)factor;
    idf = idf < 1 ? 1 : idf; idf = idf > 2 ? 2 : idf;
    k.indfor = idf;
    k.forfrac = SU(factor, (real)idf);
    k.selffac = MU(water, k.forfac);
    factor = DV(SU(tavel[lay], 188.0f), 7.2f);
    int ids = (int)factor - 7;
    ids = ids < 1 ? 1 : ids; ids = ids > 9 ? 9 : ids;
    k.indself = ids;
    k.selffrac = SU(factor, (real)(ids + 7));
  }
  for (int i = 0; i < 6; ++i) { k.col[i] = MU(1.0e-20f, wkl[rsc_row(i) + RSC_MX * lay]); k.fb[i] = false; }
  k.colmol = AD(MU(1.0e-20f, coldry[lay]), k.col[0]);
  for (int i = 1; i < 6; ++i) if (i != 2 && EQ0(k.col[i])) { k.col[i] = MU(1.0e-32f, coldry[lay]); k.fb[i] = true; }
  real co2reg = MU(3.55e-24f, coldry[lay]);
  k.diff = SU(k.col[1], co2reg);
  k.E = rsw_exp(DV(-1919.4f, tavel[lay]));
  k.den = MU(8.7604e-4f, tavel[lay]);
  k.co2mult = DV(MU(MU(k.diff, 272.63f), k.E), k.den);
  real compfp = SU(1.0f, fp);
  k.compfp = compfp;
  k.fac10 = MU(compfp, ft);
  k.fac00 = MU(compfp, SU(1.0f, ft));
  k.fac11 = MU(fp, ft1);
  k.fac01 = MU(fp, SU(1.0f, ft1));
  k.plog = plog; k.fp = fp; k.ft = ft; k.ft1 = ft1; k.water = water; k.scalefac = scalefac;
  k.jp = jpv; k.jt = jtv; k.jt1 = jt1v;
  return k;
}

// Constants as the f32 words the forward uses, widened.
#define RSC_E20 ((double)1.0e-20f)
#define RSC_E32 ((double)1.0e-32f)
#define RSC_CO2R ((double)3.55e-24f)
#define RSC_K272 ((double)272.63f)
#define RSC_K1919 ((double)1919.4f)
#define RSC_K876 ((double)8.7604e-4f)
#define RSC_K72 ((double)7.2f)

// Local partials shared by TL and AD (one set, so the pair is an exact transpose before the final f32 roundings).
struct RscD { double fp_p, sc_p, sc_T, wa_w, wa_c, ff_sc, ff_wa, ffr_T, sf_wa, sf_ff, sfr_T, x_T, cm_diff, cm_x, cm_T; bool bad; };
__device__ __forceinline__ RscD rsc_partials(const RscP &k, double p, double T, double c, double w0) {
  RscD d;
  const double stpfac = (double)__fdiv_rn(296.0f, 1013.0f);
  d.fp_p = -5.0 / p;                                   // d fp / d p   (d plog = dp/p)
  d.sc_p = stpfac / T;                                 // d scalefac / d p
  d.sc_T = -(p * stpfac) / (T * T);                    // d scalefac / d T
  d.wa_w = 1.0 / c;                                    // d water / d w0
  d.wa_c = -w0 / (c * c);                              // d water / d c
  double opw = 1.0 + (double)k.water;
  d.ff_sc = 1.0 / opw;                                 // d forfac / d scalefac
  d.ff_wa = -(double)k.scalefac / (opw * opw);         // d forfac / d water
  d.ffr_T = k.trop ? -1.0 / 36.0 : 1.0 / 36.0;         // d forfrac / d T
  d.sf_wa = k.trop ? (double)k.forfac : 0.0;           // d selffac / d water (explicit)
  d.sf_ff = k.trop ? (double)k.water : 0.0;            // d selffac / d forfac
  d.sfr_T = k.trop ? 1.0 / RSC_K72 : 0.0;              // d selffrac / d T
  d.x_T = RSC_K1919 / (T * T);                         // d (-1919.4/T) / d T
  double E = (double)k.E, den = (double)k.den;
  d.cm_diff = RSC_K272 * E / den;                      // d co2mult / d diff
  d.cm_x = RSC_K272 * (double)k.diff * E / den;        // d co2mult / d x  (dE = E dx)
  d.cm_T = -(double)k.co2mult * RSC_K876 / den;        // d co2mult / d T through the denominator
  d.bad = !isfinite(d.fp_p) || !isfinite(d.sc_p) || !isfinite(d.sc_T) || !isfinite(d.wa_w) || !isfinite(d.wa_c) ||
          !isfinite(d.ff_sc) || !isfinite(d.ff_wa) || !isfinite(d.x_T) || !isfinite(d.cm_diff) || !isfinite(d.cm_x) ||
          !isfinite(d.cm_T) || !isfinite(p) || !isfinite(T) || !isfinite(c) || !isfinite(w0);
  return d;
}

// step6-radiation (2026-11-07): molecule-unit storage scale, shared with rsw_inatm_layers_b (rationale in
// rlw_inatm.ad.cu). The inputs coldry and wkl are molecules/cm2: their tangents arrive stored as t * 2^-72 and their
// cotangents are stored as b * 2^72. Exact (power of two, in double, before the one f32 rounding).
#define RSC_MOL_T 0x1p72
#define RSC_MOL_B 0x1p72

#define RSC_PROLOGUE \
  long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x; \
  if (idx >= (long long)ncol * nlayers) return; \
  int col = (int)(idx / nlayers); int lay = (int)(idx % nlayers); \
  size_t o = (size_t)col * nlayers; size_t om = (size_t)col * RSC_MX * nlayers;

// Harness only (not in launch_abi): the 23 forward output words from rsc_primal, same signature as the forward.
extern "C" __global__ void rsw_setcoef_b__check(int ncol, int nlayers, const real *__restrict__ tab,
    const real *__restrict__ pavel, const real *__restrict__ tavel, const real *__restrict__ coldry, const real *__restrict__ wkl,
    int *jp, int *jt, int *jt1, int *indself, int *indfor, int *trop_flag, int *low_flag,
    real *colh2o, real *colco2, real *colo3, real *coln2o, real *colch4, real *colo2, real *colmol, real *co2mult,
    real *selffac, real *selffrac, real *forfac, real *forfrac, real *fac00, real *fac01, real *fac10, real *fac11) {
  RSC_PROLOGUE
  RscP k = rsc_primal(lay, tab, pavel + o, tavel + o, coldry + o, wkl + om);
  size_t j = o + lay;
  jp[j] = k.jp; jt[j] = k.jt; jt1[j] = k.jt1; indself[j] = k.indself; indfor[j] = k.indfor; trop_flag[j] = k.trop; low_flag[j] = k.low;
  colh2o[j] = k.col[0]; colco2[j] = k.col[1]; colo3[j] = k.col[2]; coln2o[j] = k.col[3]; colch4[j] = k.col[4]; colo2[j] = k.col[5];
  colmol[j] = k.colmol; co2mult[j] = k.co2mult; selffac[j] = k.selffac; selffrac[j] = k.selffrac; forfac[j] = k.forfac;
  forfrac[j] = k.forfrac; fac00[j] = k.fac00; fac01[j] = k.fac01; fac10[j] = k.fac10; fac11[j] = k.fac11;
}

extern "C" __global__ void rsw_setcoef_b__tl(int ncol, int nlayers, const real *__restrict__ tab,
    const real *__restrict__ pavel, const real *__restrict__ tavel, const real *__restrict__ coldry, const real *__restrict__ wkl,
    const float *d_pavel, const float *d_tavel, const float *d_coldry, const float *d_wkl,
    float *d_colh2o, float *d_colco2, float *d_colo3, float *d_coln2o, float *d_colch4, float *d_colo2, float *d_colmol,
    float *d_co2mult, float *d_selffac, float *d_selffrac, float *d_forfac, float *d_forfrac,
    float *d_fac00, float *d_fac01, float *d_fac10, float *d_fac11, int *failure) {
  RSC_PROLOGUE
  size_t j = o + lay;
  const real *wk = wkl + om + RSC_MX * lay;
  const float *dwk = d_wkl + om + RSC_MX * lay;
  RscP k = rsc_primal(lay, tab, pavel + o, tavel + o, coldry + o, wkl + om);
  double p = pavel[j], T = tavel[j], c = coldry[j];
  RscD q = rsc_partials(k, p, T, c, (double)wk[0]);
  double dp = d_pavel[j], dT = d_tavel[j], dc = RSC_MOL_T * (double)d_coldry[j], dw[6];
  for (int i = 0; i < 6; ++i) dw[i] = RSC_MOL_T * (double)dwk[rsc_row(i)];
  double dfp = q.fp_p * dp, dft = dT / 15.0;
  double dwa = q.wa_w * dw[0] + q.wa_c * dc;
  double dsc = q.sc_p * dp + q.sc_T * dT;
  double dff = q.ff_sc * dsc + q.ff_wa * dwa;
  double dcol[6];
  for (int i = 0; i < 6; ++i) dcol[i] = k.fb[i] ? RSC_E32 * dc : RSC_E20 * dw[i];
  double ddiff = dcol[1] - RSC_CO2R * dc;
  double dcm = q.cm_diff * ddiff + q.cm_x * (q.x_T * dT) + q.cm_T * dT;
  double fp = k.fp, ft = k.ft, ft1 = k.ft1, cf = k.compfp;
  double v[16] = {dcol[0], dcol[1], dcol[2], dcol[3], dcol[4], dcol[5], RSC_E20 * dc + dcol[0], dcm,
                  q.sf_wa * dwa + q.sf_ff * dff, q.sfr_T * dT, dff, q.ffr_T * dT,
                  -dfp * (1.0 - ft) - cf * dft, dfp * (1.0 - ft1) - fp * dft, -dfp * ft + cf * dft, dfp * ft1 + fp * dft};
  float *out[16] = {d_colh2o, d_colco2, d_colo3, d_coln2o, d_colch4, d_colo2, d_colmol, d_co2mult,
                    d_selffac, d_selffrac, d_forfac, d_forfrac, d_fac00, d_fac01, d_fac10, d_fac11};
  bool bad = q.bad || !isfinite(dp) || !isfinite(dT) || !isfinite(dc);
  for (int i = 0; i < 6; ++i) bad |= !isfinite(dw[i]);
  // A zero tangent is written as +0 (the frac products give -0 for a zero direction: -0*(1-ft) - cf*0).
  for (int i = 0; i < 16; ++i) { float t = (float)v[i]; if (t == 0.0f) t = 0.0f; out[i][j] = t; bad |= !isfinite(t); }
  if (bad) atomicExch(failure, 1);
}

extern "C" __global__ void rsw_setcoef_b__ad(int ncol, int nlayers, const real *__restrict__ tab,
    const real *__restrict__ pavel, const real *__restrict__ tavel, const real *__restrict__ coldry, const real *__restrict__ wkl,
    float *b_pavel, float *b_tavel, float *b_coldry, float *b_wkl,
    float *b_colh2o, float *b_colco2, float *b_colo3, float *b_coln2o, float *b_colch4, float *b_colo2, float *b_colmol,
    float *b_co2mult, float *b_selffac, float *b_selffrac, float *b_forfac, float *b_forfrac,
    float *b_fac00, float *b_fac01, float *b_fac10, float *b_fac11, int *failure) {
  RSC_PROLOGUE
  size_t j = o + lay;
  const real *wk = wkl + om + RSC_MX * lay;
  float *bwk = b_wkl + om + RSC_MX * lay;
  RscP k = rsc_primal(lay, tab, pavel + o, tavel + o, coldry + o, wkl + om);
  double p = pavel[j], T = tavel[j], c = coldry[j];
  RscD q = rsc_partials(k, p, T, c, (double)wk[0]);
  float *in[16] = {b_colh2o, b_colco2, b_colo3, b_coln2o, b_colch4, b_colo2, b_colmol, b_co2mult,
                   b_selffac, b_selffrac, b_forfac, b_forfrac, b_fac00, b_fac01, b_fac10, b_fac11};
  double y[16]; bool bad = q.bad;
  for (int i = 0; i < 16; ++i) { y[i] = (double)in[i][j]; in[i][j] = 0.0f; bad |= !isfinite(y[i]); }
  double fp = k.fp, ft = k.ft, ft1 = k.ft1, cf = k.compfp;
  // fac00 fac01 fac10 fac11 -> fp, ft, ft1
  double gfp = -y[12] * (1.0 - ft) + y[13] * (1.0 - ft1) - y[14] * ft + y[15] * ft1;
  double gft = -y[12] * cf + y[14] * cf;
  double gft1 = -y[13] * fp + y[15] * fp;
  double gp = q.fp_p * gfp, gT = (gft + gft1) / 15.0, gc = 0.0, gw[6] = {0, 0, 0, 0, 0, 0};
  // co2mult -> diff, x(T), T
  double gdiff = q.cm_diff * y[7];
  gT += q.cm_x * y[7] * q.x_T + q.cm_T * y[7];
  double gcol[6] = {y[0], y[1], y[2], y[3], y[4], y[5]};
  gcol[1] += gdiff; gc += -RSC_CO2R * gdiff;
  // colmol -> c, colh2o
  gc += RSC_E20 * y[6]; gcol[0] += y[6];
  for (int i = 0; i < 6; ++i) { if (k.fb[i]) gc += RSC_E32 * gcol[i]; else gw[i] += RSC_E20 * gcol[i]; }
  // selffac, selffrac, forfac, forfrac
  double gff = y[10] + q.sf_ff * y[8];
  double gwa = q.sf_wa * y[8];
  gT += q.sfr_T * y[9] + q.ffr_T * y[11];
  double gsc = q.ff_sc * gff; gwa += q.ff_wa * gff;
  gp += q.sc_p * gsc; gT += q.sc_T * gsc;
  gw[0] += q.wa_w * gwa; gc += q.wa_c * gwa;
  float t;
  t = (float)((double)b_pavel[j] + gp); b_pavel[j] = t; bad |= !isfinite(t);
  t = (float)((double)b_tavel[j] + gT); b_tavel[j] = t; bad |= !isfinite(t);
  t = (float)((double)b_coldry[j] + RSC_MOL_B * gc); b_coldry[j] = t; bad |= !isfinite(t);
  for (int i = 0; i < 6; ++i) { float *w = bwk + rsc_row(i); t = (float)((double)*w + RSC_MOL_B * gw[i]); *w = t; bad |= !isfinite(t); }
  if (bad) atomicExch(failure, 1);
}
